import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares

def trans(x=0,y=0,z=0):
 T=np.eye(4);T[:3,3]=[x,y,z];return T
def rx(a):
 T=np.eye(4);T[:3,:3]=Rot.from_rotvec([a,0,0]).as_matrix();return T
def rz(a):
 T=np.eye(4);T[:3,:3]=Rot.from_rotvec([0,0,a]).as_matrix();return T
def fk(q):
 T=np.eye(4)
 for a,al,d,t in zip([0,0,0,.0825,-.0825,0,.088],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2],[.333,0,.316,0,.384,0,0],q):
  T=T@trans(x=a)@rx(al)@trans(z=d)@rz(t)
 return T
PY"}));
