def ik(xyz,R=None,seed=None):
 seed=q.copy() if seed is None else seed
 def err(qq):
  T=worldfk(qq); out=list((T[:3,3]-xyz)*5)
  if R is not None: out.extend(Rot.from_matrix(R@T[:3,:3].T).as_rotvec())
  out.extend((qq-seed)*.015)
  return out
